# You are given two strings s and t. String t is generated by randomly shuffling
# s and then adding one more letter at a random position.
# Return the letter that was added to t.

# https://leetcode.com/problems/find-the-difference/

# Beats 100% in runtime and memory!
class Solution(object):
    def findTheDifference(self, s, t):
        return chr(reduce(lambda x,y:x^y, map(ord, s+t)))
